//! The desktop and the lerobot-nexarm driver must speak the same CommProtocol bytes.
//!
//! `fixtures/nexarm_protocol_vectors.json` is generated by lerobot-nexarm's
//! `scripts/gen-nexarm-protocol-vectors.py` and refreshed here by `scripts/sync-protocol-vectors`; its
//! pytest checks the same vectors against the Python driver.

use nexarm_desktop::protocol::{Decoded, Decoder, encode};
use serde_json::Value;

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap()).collect()
}

fn vectors() -> Vec<Value> {
    let doc: Value = serde_json::from_str(include_str!("fixtures/nexarm_protocol_vectors.json")).unwrap();
    doc["vectors"].as_array().unwrap().clone()
}

#[test]
fn requests_encode_to_the_golden_bytes() {
    let mut checked = 0;
    for v in vectors().iter().filter(|v| v["kind"] == "request") {
        let (id, cmd) = (v["id"].as_u64().unwrap() as u8, v["cmd"].as_u64().unwrap() as u8);
        assert_eq!(encode(id, cmd, &unhex(v["args"].as_str().unwrap())), unhex(v["frame"].as_str().unwrap()), "{}", v["name"]);
        checked += 1;
    }
    assert!(checked >= 7, "only {checked} request vectors");
}

#[test]
fn every_frame_decodes_as_the_driver_decodes_it() {
    for v in vectors() {
        let frame = unhex(v["frame"].as_str().unwrap());
        let mut d = Decoder::default();
        d.push(&frame);
        match (v["checksum"].as_str().unwrap(), d.next_decoded()) {
            ("bad", Some(Decoded::BadChecksum(raw))) => assert_eq!(raw, frame, "{}", v["name"]),
            ("full" | "short", Some(Decoded::Frame(f))) => {
                assert_eq!((f.id as u64, f.cmd as u64), (v["id"].as_u64().unwrap(), v["cmd"].as_u64().unwrap()), "{}", v["name"]);
                assert_eq!(f.data, unhex(v["args"].as_str().unwrap()), "{}", v["name"]);
                assert_eq!(f.raw, frame);
            }
            (kind, other) => panic!("{}: expected a {kind} frame, got {other:?}", v["name"]),
        }
    }
}

#[test]
fn the_vectors_cover_the_lerobot_bridge_commands() {
    let cmds: Vec<u64> = vectors().iter().map(|v| v["cmd"].as_u64().unwrap()).collect();
    for c in [56, 68, 96, 97, 98] {
        assert!(cmds.contains(&c), "no vector for CMD {c}");
    }
}
